// Tentativa 1: any. Entra o que for, sai o que for, e ninguém fica a saber o quê.
function identidadeAny(valor: any): any {
  return valor;
}

const nome = identidadeAny("Ada");
// nome: any -- o compilador deixou de ter opinião sobre isto
try {
  console.log(nome.toFixed(2)); // erro só em execução: as strings não têm toFixed
} catch (erro) {
  console.log(erro instanceof TypeError); // true
}

// Tentativa 2: uma sobrecarga por tipo. Correta, e insustentável.
function identidade(valor: string): string;
function identidade(valor: number): number;
function identidade(valor: boolean): boolean;
function identidade(valor: any): any {
  return valor;
}

const texto = identidade("Ada"); // string
const idade = identidade(36); // number
console.log(texto.toUpperCase(), idade.toFixed(1)); // ADA 36.0

// @ts-expect-error não há sobrecarga para arrays: cada tipo novo exige mais uma linha
const lista = identidade([1, 2, 3]);

function primeiro<T>(itens: T[]): T | undefined {
  return itens.length > 0 ? itens[0] : undefined;
}

const n = primeiro([10, 20, 30]);
// n: number | undefined

const s = primeiro(["Ada", "Alan"]);
// s: string | undefined

console.log(n, s); // 10 Ada

// O T não é um valor: vive só no sistema de tipos e desaparece no JavaScript gerado
function espreitar<T>(itens: T[]): T | undefined {
  // @ts-expect-error T é um parâmetro de tipo, não uma variável que se possa ler
  console.log(T);
  return itens[0];
}

function primeiro<T>(itens: T[]): T | undefined {
  return itens.length > 0 ? itens[0] : undefined;
}

// Na esmagadora maioria das chamadas o argumento de tipo escreve-se sozinho
const a = primeiro([10, 20]); // T = number, a: number | undefined
const b = primeiro(["Ada"]); // T = string, b: string | undefined
console.log(a, b); // 10 Ada

// Caso 1: não há por onde inferir. Um array vazio dá T = never,
// e o resultado colapsa em undefined, que não serve para nada.
const nada = primeiro([]); // nada: undefined
const tipado = primeiro<string>([]); // tipado: string | undefined
console.log(nada, tipado); // undefined undefined

// Caso 2: a inferência acerta, mas estreita demais para o que se pretende
function criarCaixa<T>(valor: T): { valor: T } {
  return { valor };
}

const estreita = criarCaixa("pendente"); // { valor: string }
// @ts-expect-error T foi inferido como string e null não cabe lá dentro
estreita.valor = null;

const larga = criarCaixa<string | null>("pendente"); // { valor: string | null }
larga.valor = null; // agora é legítimo
console.log(larga.valor); // null

function par<T, U>(a: T, b: U): [T, U] {
  return [a, b];
}

const registo = par("idade", 36); // [string, number]
console.log(registo[0], registo[1]); // idade 36

// Os dois parâmetros são independentes: nada obriga T e U a serem diferentes
const iguais = par(1, 2); // [number, number]
console.log(iguais[0] + iguais[1]); // 3

function trocar<T, U>(entrada: [T, U]): [U, T] {
  return [entrada[1], entrada[0]];
}

const trocado = trocar(registo); // [number, string]
console.log(trocado[0].toFixed(0), trocado[1].toUpperCase()); // 36 IDADE

// @ts-expect-error com um argumento de tipo escrito à mão é preciso escrevê-los todos
const incompleto = par<string>("idade", 36);

function mapear<T, U>(itens: T[], fn: (item: T) => U): U[] {
  const saida: U[] = [];
  for (const item of itens) {
    saida.push(fn(item));
  }
  return saida;
}

// T vem do primeiro argumento; U vem do que o callback devolve
const comprimentos = mapear(["Ada", "Grace"], (nome) => nome.length);
// comprimentos: number[], e o parâmetro nome já é string sem anotação nenhuma
console.log(comprimentos.join(", ")); // 3, 5

const etiquetas = mapear([1, 2, 3], (n) => `n${n}`);
// etiquetas: string[]
console.log(etiquetas.join(" ")); // n1 n2 n3

// @ts-expect-error o callback recebe string, por isso toFixed não existe
const erro = mapear(["Ada"], (nome) => nome.toFixed(2));

// Arrow genérica: os parâmetros de tipo vão antes da lista de parâmetros
const ultimo = <T>(itens: T[]): T | undefined =>
  itens.length > 0 ? itens[itens.length - 1] : undefined;

console.log(ultimo([1, 2, 3])); // 3

// Num ficheiro .tsx o <T> sozinho seria lido como o início de uma etiqueta JSX;
// aí escreve-se <T,> com vírgula. Num ficheiro .ts não é preciso.

// A anotação também pode viver na variável, e a arrow fica sem tipos nenhuns
const envolver: <T>(valor: T) => T[] = (valor) => [valor];
console.log(envolver("Ada")); // [ 'Ada' ]

// Quando as incógnitas deixam de ser duas, um nome descritivo poupa releituras
function converterCada<TEntrada, TSaida>(
  itens: TEntrada[],
  converter: (item: TEntrada) => TSaida,
): TSaida[] {
  return itens.map(converter);
}

console.log(converterCada([1.5, 2.25], (n) => n.toFixed(1)).join("|")); // 1.5|2.3

// Genérico inútil: T aparece uma só vez, no parâmetro. Não liga nada a nada.
function registar<T>(valor: T): void {
  console.log(String(valor));
}
registar<number>(1); // 1

// A mesma função, sem a cerimónia e com exatamente a mesma segurança
function registarSimples(valor: unknown): void {
  console.log(String(valor));
}
registarSimples(1); // 1

// Pior do que inútil: T aparece só no retorno, e passa a ser um desejo
function lerJson<T>(texto: string): T {
  return JSON.parse(texto) as T;
}

const config = lerJson<{ porta: number }>('{"porta": 8080}');
console.log(config.porta.toFixed(0)); // 8080

const vazio = lerJson<{ porta: number }>("{}");
// O tipo promete number; em execução vem undefined e ninguém foi avisado
console.log(vazio.porta); // undefined

