function ultimo<T>(itens: T[]): T | undefined {
  return itens.length > 0 ? itens[itens.length - 1] : undefined;
}

const n = ultimo([10, 20, 30]); // number | undefined
const s = ultimo(["a", "b"]); // string | undefined
const nenhum = ultimo<boolean>([]); // boolean | undefined

console.log(n, s, nenhum); // 30 b undefined

function emparelhar<T, U>(esquerda: T[], direita: U[]): [T, U][] {
  const total = Math.min(esquerda.length, direita.length);
  const saida: [T, U][] = [];
  for (let i = 0; i < total; i += 1) {
    saida.push([esquerda[i], direita[i]]);
  }
  return saida;
}

const pares = emparelhar(["a", "b", "c"], [1, 2]);
// pares: [string, number][] -- o terceiro elemento da esquerda fica de fora
console.log(pares.map((p) => `${p[0]}=${p[1]}`).join(", ")); // a=1, b=2

const vazio = emparelhar<string, number>([], []);
console.log(vazio.length); // 0

function compor<T, U, V>(
  primeira: (entrada: T) => U,
  segunda: (intermedio: U) => V,
): (entrada: T) => V {
  return (entrada) => segunda(primeira(entrada));
}

const comprimento = (texto: string): number => texto.length;
const parOuImpar = (n: number): string => (n % 2 === 0 ? "par" : "impar");

const classificar = compor(comprimento, parOuImpar);
// classificar: (entrada: string) => string
console.log(classificar("Ada")); // impar
console.log(classificar("Alan")); // par
console.log(classificar("Grace")); // impar

// @ts-expect-error o retorno da primeira (string) não encaixa na entrada da segunda (number)
const invalida = compor(parOuImpar, parOuImpar);

function agruparPor<T, C>(itens: T[], obterChave: (item: T) => C): Map<C, T[]> {
  const grupos = new Map<C, T[]>();
  for (const item of itens) {
    const chave = obterChave(item);
    const atual = grupos.get(chave);
    if (atual === undefined) {
      grupos.set(chave, [item]);
    } else {
      atual.push(item);
    }
  }
  return grupos;
}

const pessoas = [
  { nome: "Ada", equipa: "backend" },
  { nome: "Grace", equipa: "backend" },
  { nome: "Alan", equipa: "frontend" },
];

const porEquipa = agruparPor(pessoas, (p) => p.equipa);
// porEquipa: Map<string, { nome: string; equipa: string }[]>
console.log(porEquipa.get("backend")?.length); // 2
console.log(porEquipa.get("frontend")?.map((p) => p.nome).join()); // Alan

const porParidade = agruparPor([1, 2, 3, 4], (n) => n % 2 === 0);
// C inferido como boolean a partir do retorno de obterChave
console.log(porParidade.get(true)?.join(",")); // 2,4
console.log(porParidade.get(false)?.join(",")); // 1,3

// @ts-expect-error a chave é boolean, por isso o texto "sim" nunca pode estar lá
console.log(porParidade.get("sim"));
